#!/usr/bin/env npx tsx
/**
 * Tenant Code Generator
 *
 * Resolves one site from tenants.json and emits the runtime module the
 * browser app consumes, plus the tenant-branded app shell. The site is
 * selected with VITE_STOR_TENANT (default: the host's only site, else "st").
 *
 * Usage: VITE_STOR_TENANT=bravo pnpm build:generated
 *
 * Generated files, in .generated/sites/<id>/:
 * - tenant.ts   (tenant module consumed by the app as $tenant/generated)
 * - app.html    (boot shell branded from src/app.template.html)
 */

import { mkdir, readFile, writeFile } from "node:fs/promises";
import { dirname, isAbsolute, join, resolve } from "node:path";

import { siteDirectory } from "../compose/compose-modules.js";
import { packageDirectory } from "../host/write-host.js";
import {
    loadTenantConfig,
    siteById,
    validateCrossSite,
    REPOSITORY_ROOT,
    TenantConfigError,
} from "../tenants/tenant-config.js";
import { generateHostConfigs } from "../tenants/host-configs.js";
import { generateTenantWranglerConfigs } from "../tenants/wrangler-config.js";
import { activeSiteId } from "../root.js";
import { brandMarkMaskUrl, wordmarkParts } from "@hearthlog/contracts/tenant/brand";
import {
    contrastRatio,
    oklch,
    themePaletteFor,
    themeVariablesCss,
    type ThemePalette,
} from "@hearthlog/contracts/tenant/theme";

const APP_TEMPLATE_PATH = join(packageDirectory("@hearthlog/shell"), "src/app.template.html");

export interface GenerateTenantOptions {
    outputPath?: string;
    appOutputPath?: string;
    generateWranglerConfigs?: boolean;
}

function repositoryPath(path: string): string {
    return isAbsolute(path) ? path : resolve(REPOSITORY_ROOT, path);
}

export async function generateTenant(
    siteId: string,
    options: GenerateTenantOptions = {},
): Promise<{ outputPath: string; appOutputPath: string; wranglerConfigs: string[] }> {
    const outputPath = repositoryPath(
        options.outputPath ?? join(siteDirectory(siteId), "tenant.ts"),
    );
    const appOutputPath = repositoryPath(
        options.appOutputPath ?? join(siteDirectory(siteId), "app.html"),
    );
    const { sites, infrastructure } = await loadTenantConfig(undefined, { only: siteId });
    validateCrossSite(sites);
    const site = siteById(sites, siteId);

    const content = `/**
 * AUTO-GENERATED by packages/tooling/src/generate/generate-tenant.ts — do not edit.
 *
 * Source: tenants.json (site "${site.id}").
 * Regenerate with: VITE_STOR_TENANT=${site.id} pnpm build:generated
 */

export const TENANT_ID = "${site.id}" as const;

export const TENANT = {
    id: "${site.id}",
    ledgerAppName: "${site.ledgerAppName}",
    title: ${JSON.stringify(site.title)},
    home: "${site.home}",
    features: ${JSON.stringify(site.features)} as const,
    ai: ${JSON.stringify(site.ai)} as const,
    developerNavVisible: ${site.developerNavVisible},
    entitiesNavVisible: ${site.entitiesNavVisible},
    dynamicEntities: ${site.dynamicEntities},
    theme: ${JSON.stringify(site.theme)} as { accent?: string },
    admin: ${site.admin},
    hostname: ${JSON.stringify(site.hostname)},
    kalApiOrigin: ${JSON.stringify(infrastructure.kalApiOrigin ?? "")}
} as const;
`;

    await mkdir(dirname(outputPath), { recursive: true });
    await writeFile(outputPath, content, "utf8");

// Brand the boot shell so the pre-app skeleton matches the tenant. The
// template keeps explicit %%BRAND_*%% markers; everything else stays
// byte-identical across tenants.
const template = await readFile(APP_TEMPLATE_PATH, "utf8");
const palettes = [themePaletteFor(site.theme.accent, "light"), themePaletteFor(site.theme.accent, "dark")] as const;
const lightTheme = palettes[0].variables;
const darkTheme = palettes[1].variables;
const themeStyle = themeVariablesCss(lightTheme);
const brandable = template
    .replaceAll("%%BRAND_MARK_MASK%%", brandMarkMaskUrl())
    .replaceAll("%%BRAND_WORDMARK%%", wordmarkHtml(site.title))
    .replaceAll("%%BRAND_TITLE%%", escapeHtml(site.title))
    .replaceAll("%%BRAND_ID%%", escapeHtml(site.id))
    .replaceAll("%%BRAND_THEME_COLOR%%", escapeHtml(lightTheme["--stor-theme-color"]))
    .replaceAll("%%BRAND_DARK_THEME%%", escapeHtml(themeVariablesCss(darkTheme)))
    .replaceAll("%%BRAND_THEME%%", escapeHtml(themeStyle));
if (/%%BRAND_[A-Z_]+%%/.test(brandable)) {
    throw new TenantConfigError(
        "app.template.html still contains unresolved %%BRAND_*%% markers",
    );
}
    await mkdir(dirname(appOutputPath), { recursive: true });
    await writeFile(appOutputPath, brandable, "utf8");

    // The site's Worker config in its own generated folder, and the Workers of its stack (the Ledger and the public
    // calendar and Gallery Workers), from the tenant files.
    const wranglerConfigs = options.generateWranglerConfigs === false
        ? []
        : [
            ...(await generateTenantWranglerConfigs(site.id)),
            ...(await generateHostConfigs(site.deployment ? site.id : "shared")),
        ];

    console.log(
        `Generated tenant module for "${site.id}" (${site.features.length} ` +
            `features, home ${site.home}, accent ${site.theme.accent ?? "default"}) ` +
            `at ${outputPath}`,
    );
    console.log(paletteReport(site.id, palettes));
    if (wranglerConfigs.length > 0) {
        console.log(
            `Generated ${wranglerConfigs.length} tenant wrangler config(s): ` +
                wranglerConfigs
                    .map((path) => path.replace(`${REPOSITORY_ROOT}/`, ""))
                    .join(", "),
        );
    }
    return { outputPath, appOutputPath, wranglerConfigs };
}

if (process.env.STOR_SKIP_TENANT_GENERATION !== "1") {
    await generateTenant(activeSiteId(), {
        generateWranglerConfigs: process.env.STOR_WRANGLER_CONFIGS !== "0",
    });
}

/** The palette the site's accent derives in each mode, and every clash with a meaning colour it resolved. */
function paletteReport(siteId: string, palettes: readonly ThemePalette[]): string {
    const lines = [`Palette for "${siteId}" from accent ${palettes[0]!.accent}:`];
    for (const palette of palettes) {
        const mode = palette.mode.padEnd(5);
        const action = palette.monochrome ? `monochrome, action in ink ${palette.action}` : `action ${palette.action}`;
        lines.push(
            `  ${mode}  ${action} (text ${palette.actionText}, ${contrastRatio(palette.action, palette.actionText).toFixed(1)}:1)` +
                ` · links ${palette.accentText} · soft ${palette.soft} · focus ${palette.focus}`,
        );
    }
    for (const palette of palettes) {
        for (const clash of palette.clashes) {
            const rule = clash.role === "now" ? "drawn in ink" : `hue turned to ${Math.round(oklch(clash.to).H)}°`;
            lines.push(
                `  ${palette.mode.padEnd(5)}  ${clash.role} ${clash.from} → ${clash.to} ` +
                    `(ΔE ${clash.distance.toFixed(3)} from the action; ${rule})`,
            );
        }
    }
    if (palettes.every((palette) => palette.clashes.length === 0)) lines.push("  no clashes with status or now");
    return lines.join("\n");
}

/** The tenant title with the brand mark in place of its first "s". */
function wordmarkHtml(title: string): string {
    const parts = wordmarkParts(title);
    if (!parts) return escapeHtml(title);
    return (
        `<span class="stor-wordmark" role="img" aria-label="${escapeHtml(title)}">` +
        `${escapeHtml(parts.before)}<span class="stor-mark"></span>${escapeHtml(parts.after)}</span>`
    );
}

function escapeHtml(value: string): string {
    return value
        .replaceAll("&", "&amp;")
        .replaceAll("<", "&lt;")
        .replaceAll(">", "&gt;")
        .replaceAll('"', "&quot;");
}
